CREATE TABLE [dbo].[RIA_PLANTILLA](	  [id_plantilla] INT NOT NULL IDENTITY(1,1)	, [descripcion] VARCHAR(200) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [cam_id] INT NOT NULL	, [tipo_llamada] SMALLINT NOT NULL	, [modo_graba_id] INT NOT NULL	, [valor] VARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [predeterminada] BIT NOT NULL DEFAULT((0))	, [status] BIT NOT NULL DEFAULT((1))	, [user_id] INT NULL	, [fecha] DATETIME NOT NULL DEFAULT(getdate())	, [replace] INT NULL DEFAULT((0))	, CONSTRAINT [PK_RIA_PLANTILLAS] PRIMARY KEY ([id_plantilla] ASC))